"""Read the sheets of an Excel workbook (made-up example)."""


def read_sheets(workbook):
    sheets = {
        name: sheet["rows"]
        for name, sheet in workbook.items()
        if sheet["rows"] and not sheet.get("hidden")
    }
    if not sheets:
        raise ValueError("The workbook has no readable sheets.")
    return sheets
